 function hostedControl(){if(loading)return `<p class="sv-account-checking" role="status">${escape(text('checking'))}</p>`;if(error)return `<div class="sv-account-error"><p role="status">${escape(text('failed'))}</p><button type="button" class="sv-account-text-button" data-account-action="retry">${escape(text('retry'))}</button></div>`;if(session.authenticated)return `<p class="sv-account-verified">${escape(text('verified'))}${session.user.displayName?`<strong>${escape(session.user.displayName)}</strong>`:''}</p><button type="button" class="sv-account-site" data-account-action="verified" ${selecting?'disabled':''}>${escape(text('useVerified'))}<span aria-hidden="true">↗</span></button>`;if(config.available)return `<a class="sv-account-site" href="${escape(signInPath())}" target="_top" data-account-action="signin">${escape(text('siteAccount'))}<span aria-hidden="true">↗</span></a><p class="sv-account-platform">${escape(text('hosted'))}</p>`;return `<p class="sv-account-platform">${escape(session.checked?text('notSignedIn'):text('unknown'))}</p><button type="button" class="sv-account-text-button" data-account-action="retry">${escape(text('retry'))}</button>`;}
