 function finishClose(){const callback=onContinue;onContinue=null;if(callback){try{callback(state());}catch{/* Completing optional onboarding must remain safe. */}}}
 function close(){if(!dialog||!isOpen())return;if(!choiceMade()){saveChoice('guest');emit();}closing=true;try{if(typeof dialog.close==='function')dialog.close();else{dialog.removeAttribute?.('open');dialog.open=false;}}finally{closing=false;}opener?.focus?.();finishClose();render();}
