 function click(event){const action=event.target?.closest?.('[data-account-action]');if(!action||action.disabled)return;switch(action.dataset.accountAction){case 'open':event.preventDefault?.();open();break;case 'guest':event.preventDefault?.();continueGuest();break;case 'close':event.preventDefault?.();close();break;case 'retry':event.preventDefault?.();void refresh();break;case 'verified':event.preventDefault?.();void useVerified();break;case 'signin':if(!config.available){event.preventDefault?.();return;}saveChoice('account');emit();break;}}
